// POSIX-family shells: same -c invocation and '...' quoting, and one emitter (POSIX sh 2017 + `local`).
#include "shell.hpp"
#include "emit_dialect.hpp"
#include <set>
namespace fs = forge::script;

namespace {
using namespace forge::script;
// Single-quoted literal as a word: '..' with ' spelled '\''.
std::string sq(const std::string& s) { return shellq::posix(s); }
bool lit_ident(const std::string& w, std::string& out) {   // 'NAME' -> NAME
    if (w.size() < 3 || w.front() != '\'' || w.back() != '\'') return false;
    out = w.substr(1, w.size() - 2);
    if (out.empty() || std::isdigit(static_cast<unsigned char>(out[0]))) return false;
    for (char c : out) if (!(std::isalnum(static_cast<unsigned char>(c)) || c == '_')) return false;
    return true;
}

struct posix_dialect : emit_dialect {
    std::set<std::string> need;
    std::vector<std::size_t> opens;   // index of the line that opened the current body
    std::string header() override {
        std::string sb = cx->target == "sh" ? "/bin/sh" : cx->target == "mksh" ? "/system/bin/sh" : cx->target == "ash" ? "/usr/bin/env -S busybox sh" : "/usr/bin/env " + cx->exe;
        std::string h = "#!" + sb + "\n# generated by `forge script --emit " + cx->target + "`; runs without FORGE\n";
        if (need.count("q")) h += "_q() { _s=$1 _o=; while :; do case $_s in *\\'*) _o=$_o${_s%%\\'*}\"'\\\\''\"; _s=${_s#*\\'};; *) break;; esac; done; printf \"'%s'\" \"$_o$_s\"; }\n";
        if (need.count("fs")) h += "_fs=$(printf '\\034')\n";
        if (need.count("platform")) h += "_platform() { case $(uname -s) in Linux) if [ -n \"${ANDROID_ROOT-}\" ]; then echo android; else echo linux; fi;; Darwin) echo macos;; FreeBSD) echo freebsd;; MINGW*|MSYS*|CYGWIN*|Windows_NT) echo windows;; *) echo other;; esac; }\n";
        return h;
    }
    // AT&T ksh93 has no `local`: locals need `typeset` inside `function f { }` (POSIX f() shares scope).
    bool ksh93() const { return cx->target == "ksh"; }
    std::string loc() const { return ksh93() ? "typeset " : "local "; }
    void open(const std::string& s) { L(s); opens.push_back(cx->lines.size()); in(); }
    void close(const std::string& s) { if (cx->lines.size() == opens.back()) L(":"); opens.pop_back(); out(); L(s); }
    void mid(const std::string& s) { if (cx->lines.size() == opens.back()) L(":"); out(); L(s); in(); opens.back() = cx->lines.size(); }

    std::string s_lit(const std::string& s) override { return sq(s); }
    std::string ref(const std::string& n, ety t, bool) override { return t == ety::Int ? "$" + n : "\"$" + n + "\""; }
    std::string arith(char op, const std::string& a, const std::string& b) override { return "$((" + a + " " + op + " " + b + "))"; }
    std::string neg(const std::string& a) override { return "$((-(" + a + ")))"; }
    std::string concat(const std::vector<std::string>& p) override { std::string o; for (auto& x : p) o += x; return o; }
    std::string i2s(const std::string& i) override { return i; }
    std::string s2i(const std::string& s) override { return "$(printf '%d' " + s + ")"; }
    std::string slen(const std::string& s) override { auto t = cx->tmp(); let(t, s, ety::Str, !cx->in_fn, true); return "${#" + t + "}"; }
    std::string cmp(const std::string& op, const std::string& a, const std::string& b, bool ints) override {
        static const std::pair<const char*, const char*> io[] = {{"==", "-eq"}, {"!=", "-ne"}, {"<", "-lt"}, {"<=", "-le"}, {">", "-gt"}, {">=", "-ge"}};
        if (ints) for (auto& [o, t] : io) if (op == o) return "[ " + a + " " + t + " " + b + " ]";
        if (op == "==") return "[ " + a + " = " + b + " ]";
        if (op == "!=") return "[ " + a + " != " + b + " ]";
        if (op == "<") return "[ " + a + " \\< " + b + " ]";
        if (op == ">") return "[ " + a + " \\> " + b + " ]";
        no("string ordering with " + op);
    }
    std::string c_and(const std::string& a, const std::string& b) override { return "{ " + a + " && " + b + "; }"; }
    std::string c_or(const std::string& a, const std::string& b) override { return "{ " + a + " || " + b + "; }"; }
    std::string c_not(const std::string& a) override { return "! { " + a + "; }"; }
    std::string c_bool(bool v) override { return v ? "true" : "false"; }
    void let(const std::string& n, const std::string& v, ety, bool global, bool decl) override {
        if (decl && !global && cx->in_fn) L(loc() + n + "; " + n + "=" + v);
        else L(n + "=" + v);
    }
    void print(const std::string& v, bool nl, bool err) override { L(std::string("printf '%s") + (nl ? "\\n" : "") + "' " + v + (err ? " >&2" : "")); }
    void if_(const std::string& c) override { open("if " + c + "; then"); }
    void else_() override { mid("else"); }
    void end_if() override { close("fi"); }
    void while_(const std::string& c) override { open("while " + c + "; do"); }
    void end_while() override { close("done"); }
    void for_(const std::string& v, const std::vector<std::string>& items) override { std::string s = "for " + v + " in"; for (auto& i : items) s += " " + i; open(s + "; do"); }
    void end_for() override { close("done"); }
    void brk() override { L("break"); }
    void cont() override { L("continue"); }
    void fn_(const std::string& name, const std::vector<std::string>& ps) override {
        open(ksh93() ? "function " + name + " {" : name + "() {");
        for (std::size_t i = 0; i < ps.size(); ++i) L(loc() + ps[i] + "; " + ps[i] + "=$" + std::to_string(i + 1));
    }
    void end_fn() override { close("}"); }
    void ret(const std::string& v) override { if (!v.empty()) L("_r=" + v); L("return 0"); }
    std::string call(const std::string& name, const std::vector<std::string>& a, bool want, ety rt) override {
        std::string s = name; for (auto& x : a) s += " " + x;
        L(s);
        if (!want) return "";
        auto t = cx->tmp(); let(t, "$_r", rt, !cx->in_fn, true); return ref(t, rt, true);
    }
    void exit_(const std::string& c) override { L("exit " + c); }
    std::string env(const std::string& n, const std::string& d) override {
        std::string name; if (!lit_ident(n, name)) no("a dynamic environment variable name");
        auto t = cx->tmp(); let(t, d, ety::Str, !cx->in_fn, true);
        if_("[ -n \"${" + name + "+x}\" ]"); let(t, "$" + name, ety::Str, !cx->in_fn, false); end_if();
        return "\"$" + t + "\"";
    }
    void setenv(const std::string& n, const std::string& v) override { std::string name; if (!lit_ident(n, name)) no("a dynamic environment variable name"); L("export " + name + "=" + v); }
    std::string test_path(const std::string& p, char k) override { return std::string("[ -") + k + " " + p + " ]"; }
    void mkdir(const std::string& p) override { L("mkdir -p -- " + p); }
    void remove(const std::string& p) override { L("rm -rf -- " + p); }
    void write(const std::string& p, const std::string& s, bool app) override { L("printf '%s' " + s + (app ? " >> " : " > ") + p); }
    std::string read(const std::string& p) override { auto t = cx->tmp(); let(t, "$(cat -- " + p + "; printf x)", ety::Str, !cx->in_fn, true); L(t + "=${" + t + "%x}"); return "\"$" + t + "\""; }
    std::string cwd() override { return "\"$(pwd -P)\""; }
    std::string platform() override { need.insert("platform"); return "\"$(_platform)\""; }
    void run(const std::string& cmd, const std::string& o, const std::string& c, bool host) override {
        need.insert("fs");
        if (host) L(o + "=$( (eval " + cmd + "); printf '\\034%d' \"$?\")");
        else L(o + "=$(sh -c " + sq(sh_wrapper()) + " _ " + cmd + ")");
        L(c + "=${" + o + "##*\"$_fs\"}; " + o + "=${" + o + "%\"$_fs\"*}");
    }
    std::string sh_quote(const std::string& v) override { need.insert("q"); return "\"$(_q " + v + ")\""; }
};
} // namespace

void forge_shell_register_posix(fs::shell_registry& r) {
    struct S { const char* name; std::vector<std::string> aliases, exes; bool tested; const char* notes; };
    const S list[] = {
        {"sh", {}, {"sh"}, true, "system POSIX sh"},
        {"bash", {}, {"bash"}, true, ""},
        {"zsh", {}, {"zsh"}, true, ""},
        {"dash", {}, {"dash"}, true, "Debian Almquist shell"},
        {"ash", {"busybox"}, {"ash", "busybox"}, true, "BusyBox ash (runs `busybox sh` when no ash binary)"},
        {"ksh", {"ksh93"}, {"ksh", "ksh93"}, true, "AT&T ksh93"},
        {"mksh", {"android", "toybox"}, {"mksh"}, true, "MirBSD Korn shell (Android's /system/bin/sh)"},
        {"oksh", {"pdksh"}, {"oksh", "pdksh"}, true, "OpenBSD ksh"},
        {"yash", {}, {"yash"}, true, ""},
        {"posh", {}, {"posh"}, false, "Policy-compliant Ordinary SHell"},
        {"osh", {"oils"}, {"osh"}, true, "Oils, POSIX/bash-compatible mode"},
        {"hush", {}, {"hush"}, true, "BusyBox hush"},
    };
    for (auto& s : list) {
        fs::shell_backend b; b.name = s.name; b.aliases = s.aliases; b.exes = s.exes; b.family = "posix"; b.golden_tested = s.tested; b.notes = s.notes;
        b.quote = fs::shellq::posix;
        b.argv = [](const std::string& exe, const std::string& sc) -> std::vector<std::string> {
            if (exe.ends_with("busybox")) return {exe, "sh", "-c", sc};
            return {exe, "-c", sc};
        };
        b.emitter = [] { return std::make_unique<posix_dialect>(); }; b.emit_tested = s.tested;
        r.add(std::move(b));
    }
}
